// Tests of the php backend (packages/compiler/src/backends/php.mjs, docs/spec/fsm.md, B-4 and B-6): the files of the
// order example are the golden files under tests/golden/php, byte for byte, in the order the backend returns them. The golden files were written by the generator once, after a review of its
// output against B-6 (docs/plans/fsm-v1/plan.md, C-5). Every generated file is also checked by the php linter, and the namespace
// that the command line passes is refused when it is not a PHP namespace.
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import test from 'node:test';
import { fileURLToPath } from 'node:url';
import { files } from '../src/backends/php.mjs';
import { normalize } from '../src/core/normalize.mjs';
import { jsonStore } from '../src/store-json/store.mjs';
import { backendTests, orderIrs } from './backend-support.mjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, '../../..');
const NAMESPACE = 'Polyspec\\FsmTest';
const NAMES = ['Order/State.php', 'Order/Event.php', 'Order/Step.php', 'Order/functions.php', 'Fsm/Code.php', 'Fsm/Error.php', 'functions.php'];

backendTests({
  kind: 'php',
  files,
  options: { phpNamespace: NAMESPACE },
  names: NAMES,
  fromOf: file => (file.startsWith('Order/') ? 'order' : 'fsm'),
  headerLines: from => ['<?php', '', `// Code generated by fsm-gen from ${from}; DO NOT EDIT.`],
});

/** The files of the order example for the namespace NAMESPACE. */
async function orderFiles() {
  const { irs, lock } = await orderIrs();
  return files(irs, lock, { phpNamespace: NAMESPACE });
}

test('the namespace is required and must be a PHP namespace of letters, digits and single backslashes', async () => {
  const { irs, lock } = await orderIrs();
  for (const phpNamespace of [undefined, '', 'Bad Name', '\\Polyspec', 'Polyspec\\', 'Polyspec\\\\FsmTest', '1Fsm', 'Poly-spec']) {
    assert.throws(() => files(irs, lock, { phpNamespace }), /php namespace/, JSON.stringify(phpNamespace));
  }
});

test('every generated php file passes the php linter (php -l)', async (t) => {
  const dir = mkdtempSync(path.join(tmpdir(), 'fsm-php-backend-'));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  for (const file of await orderFiles()) {
    const target = path.join(dir, file.path);
    mkdirSync(path.dirname(target), { recursive: true });
    writeFileSync(target, file.content);
    const lint = spawnSync('php', ['-l', target], { encoding: 'utf8' });
    assert.equal(lint.status, 0, `${file.path}: ${lint.stdout}${lint.stderr}`);
  }
});

test('the loader src/functions.php requires the functions of every machine, in definition order, with no test of another implementation', async () => {
  const { definitions, lock, findings } = await jsonStore(path.join(ROOT, 'contracts')).load();
  assert.deepEqual(findings, []);
  const irs = definitions.map(normalize);
  const loader = files(irs, lock, { phpNamespace: NAMESPACE }).find(file => file.path === 'functions.php').content;
  const pascal = key => key.split('_').map(word => word[0].toUpperCase() + word.slice(1)).join('');
  assert.deepEqual(
    loader.split('\n').filter(line => line.startsWith('require_once') || line.includes('function_exists')),
    irs.map(ir => `require_once __DIR__ . '/${pascal(ir.machine)}/functions.php';`),
  );
  assert.ok(irs.length > 1, 'the root holds several machines, so the loader is tested with more than one');
});

test('a caller without strict_types gets E_UNKNOWN_CODE for a value that is not an int, never a converted code (B-6)', async (t) => {
  const dir = mkdtempSync(path.join(tmpdir(), 'fsm-php-coercion-'));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  for (const file of await orderFiles()) {
    const target = path.join(dir, 'src', file.path);
    mkdirSync(path.dirname(target), { recursive: true });
    writeFileSync(target, file.content);
  }
  // The script has no declare(strict_types=1), so its calls are in coercive mode, as the calls of an application that does not
  // declare it. The loader is required by hand, and the classes are autoloaded from the generated files.
  const script = path.join(dir, 'caller.php');
  writeFileSync(script, String.raw`<?php
$root = $argv[1];
spl_autoload_register(static function (string $class) use ($root): void {
    $prefix = 'Polyspec\\FsmTest\\';
    if (!str_starts_with($class, $prefix)) return;
    $file = $root . '/src/' . str_replace('\\', '/', substr($class, strlen($prefix))) . '.php';
    if (is_file($file)) require $file;
});
require $root . '/src/functions.php';
foreach (['string' => '2', 'float' => 2.0, 'fraction' => 2.5, 'bool' => true, 'null' => null, 'int' => 2] as $name => $value) {
    try {
        $state = \Polyspec\FsmTest\Order\fromCode($value);
        echo "RESULT $name {$state->name}\n";
    } catch (\Polyspec\FsmTest\Fsm\Error $error) {
        echo "RESULT $name {$error->getCode()}\n";
    }
}
`);
  const run = spawnSync('php', ['-d', 'error_reporting=0', script, dir], { encoding: 'utf8' });
  assert.equal(run.status, 0, run.stderr);
  assert.deepEqual(
    run.stdout.split('\n').filter(line => line.startsWith('RESULT ')),
    ['RESULT string E_UNKNOWN_CODE', 'RESULT float E_UNKNOWN_CODE', 'RESULT fraction E_UNKNOWN_CODE',
      'RESULT bool E_UNKNOWN_CODE', 'RESULT null E_UNKNOWN_CODE', 'RESULT int Paid'],
  );
});
